const fs = require("fs");
const path = require("path");
const { spawnSync } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const dir = fs.mkdtempSync("/tmp/proj-");
fs.writeFileSync(path.join(dir, "index.js"), 'import { Buffer } from "node:buffer";\nexport default { fetch() { return new Response(Buffer.from("hi").toString("base64")); } };\n');
fs.writeFileSync(path.join(dir, "wrangler.json"), JSON.stringify({ name: "w", main: "index.js", compatibility_date: "2026-08-04" }));
const out = path.join(dir, "out");
const r = spawnSync(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "deploy", "--dry-run", "--outdir", out], { cwd: dir, encoding: "utf8", timeout: 80000, env: { ...process.env, CI: "1", WRANGLER_SEND_METRICS: "false", NO_COLOR: "1" } });
const text = (r.stdout || "") + (r.stderr || "");
if (text.includes("wasn't found on the file system but is built into node")) symptom("compatibility_date 2026-08-04 without a flag is bundled as if nodejs_compat were off");
if (r.status !== 0) broken("wrangler deploy --dry-run exited " + r.status + ": " + text.slice(-800));
if (!fs.existsSync(path.join(out, "index.js"))) broken("no bundle written: " + text.slice(-800));
console.log("OK: node:buffer bundled with Node.js compatibility on from the compatibility date");

